import { Button } from '@refy-design/web';
import { HoverCard } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import { PersonCell } from '@refy-design/web';
import { useState } from 'react';
function HoverCardExample() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <HoverCard
        content={<PersonCell name="Ana Lima" secondary="Designer · Creative team" />}
      >
        <Button variant="ghost" onClick={() => setOpen(true)}>
          Ana Lima
        </Button>
      </HoverCard>
      <Modal open={open} onClose={() => setOpen(false)} title="Ana Lima's profile">
        <PersonCell name="Ana Lima" secondary="ana@example.com" />
        <p>Owns the library and the material reviews.</p>
      </Modal>
    </>
  );
}
export function Example() {
  return <HoverCardExample />;
}
